css:
.pivot-sim-container {
    padding: 28px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: 'Courier New', 'SF Mono', 'Fira Code', monospace;
    color: #c9d1d9;
}
.pivot-sim-header {
    border-left: 4px solid #00bfff;
    padding: 24px 28px;
    margin-bottom: 24px;
    background: rgba(0,191,255,0.04);
    position: relative;
}
.pivot-sim-header-tag {
    display: inline-block;
    background: rgba(0,191,255,0.15);
    color: #00bfff;
    font-size: 0.65rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    padding: 4px 12px;
    border-radius: 3px;
    margin-bottom: 10px;
}
.pivot-sim-header h1 {
    color: #00bfff;
    font-size: 1.6rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0 0 6px 0;
    font-weight: 700;
}
.pivot-sim-subtitle {
    color: #8b9dc3;
    font-size: 0.82rem;
    margin: 0;
    letter-spacing: 0.04em;
}
.pivot-sim-period-bar {
    display: flex;
    align-items: center;
    gap: 8px;
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 6px;
    padding: 12px 20px;
    margin-bottom: 24px;
    font-size: 0.9rem;
    color: #8b9dc3;
}
.pivot-sim-period-bar span:nth-child(2),
.pivot-sim-period-bar span:nth-child(4) {
    color: #00bfff;
    font-weight: 700;
    font-size: 1.1rem;
}
.pivot-sim-round-tag {
    margin-left: auto;
    background: rgba(0,191,255,0.12);
    color: #00bfff;
    padding: 4px 14px;
    border-radius: 4px;
    font-size: 0.75rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}
.pivot-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(155px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.pivot-sim-kpi-card {
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    padding: 18px 14px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease;
}
.pivot-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00bfff, #0066cc);
}
.pivot-sim-kpi-card:hover {
    border-color: #2a3f5f;
}
.pivot-sim-kpi-danger::before {
    background: linear-gradient(90deg, #ff4757, #ff6b81);
}
.pivot-sim-kpi-label {
    color: #8b9dc3;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 8px;
}
.pivot-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #e0e6f0;
}
.pivot-sim-kpi-accent {
    color: #00bfff;
}
.pivot-sim-kpi-green {
    color: #00ff88;
}
.pivot-sim-kpi-danger .pivot-sim-kpi-value {
    color: #ff4757;
}
.pivot-sim-briefing {
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    margin-bottom: 24px;
    overflow: hidden;
}
.pivot-sim-briefing-bar {
    background: rgba(0,191,255,0.08);
    padding: 12px 20px;
    font-size: 0.78rem;
    color: #00bfff;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    display: flex;
    align-items: center;
    gap: 8px;
    border-bottom: 1px solid #1e2d42;
}
.pivot-sim-briefing-icon {
    font-size: 0.7rem;
}
.pivot-sim-briefing-body {
    padding: 20px;
    font-size: 0.85rem;
    line-height: 1.7;
    color: #9aa5b4;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.pivot-sim-controls {
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
}
.pivot-sim-controls h3 {
    color: #00bfff;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #1e2d42;
}
.pivot-sim-control-group {
    margin-bottom: 20px;
}
.pivot-sim-control-group label {
    display: block;
    color: #8b9dc3;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 8px;
}
.pivot-sim-range-row {
    display: flex;
    align-items: center;
    gap: 12px;
}
.pivot-sim-range-end {
    color: #8b9dc3;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    min-width: 80px;
}
.pivot-sim-range-end:last-child {
    text-align: right;
}
.pivot-sim-range {
    flex: 1;
    -webkit-appearance: none;
    appearance: none;
    height: 6px;
    background: #1e2d42;
    border-radius: 3px;
    outline: none;
}
.pivot-sim-range::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: #00bfff;
    cursor: pointer;
    box-shadow: 0 0 8px rgba(0,191,255,0.4);
    transition: box-shadow 0.2s ease;
}
.pivot-sim-range::-webkit-slider-thumb:hover {
    box-shadow: 0 0 14px rgba(0,191,255,0.7);
}
.pivot-sim-range::-moz-range-thumb {
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: #00bfff;
    cursor: pointer;
    border: none;
    box-shadow: 0 0 8px rgba(0,191,255,0.4);
}
.pivot-sim-range-readout {
    text-align: center;
    color: #00bfff;
    font-size: 1.1rem;
    font-weight: 700;
    margin-top: 6px;
}
.pivot-sim-controls input[type="number"] {
    background: #0a0f1e;
    border: 1px solid #2a3f5f;
    color: #e0e6f0;
    border-radius: 5px;
    padding: 10px 14px;
    width: 100%;
    font-family: 'Courier New', monospace;
    font-size: 1rem;
    transition: border-color 0.2s ease;
}
.pivot-sim-controls input[type="number"]:focus {
    border-color: #00bfff;
    outline: none;
    box-shadow: 0 0 0 2px rgba(0,191,255,0.15);
}
.pivot-sim-input-hint {
    display: block;
    color: #8b9dc3;
    font-size: 0.7rem;
    margin-top: 4px;
}
.pivot-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-top: 24px;
}
.pivot-sim-submit-btn {
    background: linear-gradient(135deg, #0077cc, #00bfff);
    border: none;
    color: #fff;
    padding: 12px 32px;
    border-radius: 6px;
    font-family: 'Courier New', monospace;
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    cursor: pointer;
    transition: box-shadow 0.2s ease, transform 0.1s ease;
}
.pivot-sim-submit-btn:hover {
    box-shadow: 0 0 16px rgba(0,191,255,0.4);
    transform: translateY(-1px);
}
.pivot-sim-undo-btn {
    background: transparent;
    border: 1px solid #2a3f5f;
    color: #8b9dc3;
    padding: 8px 18px;
    border-radius: 5px;
    font-family: 'Courier New', monospace;
    font-size: 0.75rem;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.pivot-sim-undo-btn:hover {
    border-color: #8b9dc3;
    color: #8b9dc3;
}
.pivot-sim-feedback {
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    margin-bottom: 24px;
    overflow: hidden;
}
.pivot-sim-feedback-bar {
    background: rgba(0,255,136,0.06);
    padding: 12px 20px;
    font-size: 0.78rem;
    color: #00ff88;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    border-bottom: 1px solid #1e2d42;
}
.pivot-sim-feedback-body {
    padding: 20px;
    font-size: 0.85rem;
    line-height: 1.7;
    color: #c9d1d9;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.pivot-sim-history {
    margin-bottom: 24px;
}
.pivot-sim-container .table {
    background: #111827;
    color: #c9d1d9;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    overflow: hidden;
    font-size: 0.8rem;
}
.pivot-sim-container .table thead th {
    background: rgba(0,191,255,0.06);
    color: #00bfff;
    border-color: #1e2d42;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 10px 12px;
}
.pivot-sim-container .table td {
    border-color: #1e2d42;
    padding: 8px 12px;
}
.pivot-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background: rgba(255,255,255,0.02);
}
.pivot-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 24px;
}
.pivot-sim-chart-box {
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    padding: 16px;
    height: 260px;
}
@media (max-width: 768px) {
    .pivot-sim-container {
        padding: 16px;
    }
    .pivot-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .pivot-sim-charts {
        grid-template-columns: 1fr;
    }
    .pivot-sim-range-row {
        flex-wrap: wrap;
    }
    .pivot-sim-range-end {
        min-width: 60px;
        font-size: 0.6rem;
    }
    .pivot-sim-btn-row {
        flex-direction: column;
    }
    .pivot-sim-submit-btn {
        width: 100%;
    }
    .pivot-sim-header h1 {
        font-size: 1.2rem;
    }
    .pivot-sim-kpi-value {
        font-size: 1.3rem;
    }
}

/* ===== El Pivote 2.0 design layer (EQIL 2026-10-22). Appended; everything below is scoped to .pivot-sim-container.pv ===== */
.pivot-sim-container.pv {
    --pv-bg: #f2f5f9; --pv-card: #ffffff; --pv-ink: #0b1f3a; --pv-ink-2: #2b3b55; --pv-ink-3: #4f5d75;
    --pv-line: #dbe2ec; --pv-line-2: #c3cede; --pv-accent: #0e7490; --pv-accent-ink: #155e75; --pv-accent-soft: #e0f2f7;
    --pv-navy: #0b1f3a; --pv-amber: #b45309; --pv-amber-soft: #fef3e2; --pv-indigo: #4338ca; --pv-indigo-soft: #eef0fd;
    --pv-bad: #b42318; --pv-bad-soft: #fdecea; --pv-ok: #166534; --pv-ok-soft: #e7f5ec; --pv-warn-soft: #fff4dc; --pv-focus: #0b3d91;
    --pv-r: 12px; --pv-r-sm: 8px; --pv-s1: 4px; --pv-s2: 8px; --pv-s3: 12px; --pv-s4: 16px; --pv-s5: 24px; --pv-s6: 32px;
    background: var(--pv-bg); color: var(--pv-ink); padding: var(--pv-s4) var(--pv-s5) var(--pv-s6); min-height: auto;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 15px; line-height: 1.45;
    box-sizing: border-box; text-align: left; color-scheme: light;
}
.pivot-sim-container.pv *, .pivot-sim-container.pv *::before, .pivot-sim-container.pv *::after { box-sizing: border-box; }
.pivot-sim-container.pv [hidden] { display: none !important; }
.pivot-sim-container.pv h1, .pivot-sim-container.pv h2, .pivot-sim-container.pv h3, .pivot-sim-container.pv p,
.pivot-sim-container.pv figure, .pivot-sim-container.pv dl, .pivot-sim-container.pv dd, .pivot-sim-container.pv blockquote { margin: 0; }

/* header */
.pivot-sim-container.pv .pv-top { display: flex; justify-content: space-between; align-items: flex-end; gap: var(--pv-s4); margin-bottom: var(--pv-s3); flex-wrap: wrap; }
.pivot-sim-container.pv .pv-kicker { font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--pv-accent-ink); margin-bottom: 2px; }
.pivot-sim-container.pv h1 { font-size: 26px; line-height: 1.15; font-weight: 750; color: var(--pv-ink); letter-spacing: -.01em; text-transform: none; }
.pivot-sim-container.pv .pv-progress { display: flex; flex-direction: column; align-items: flex-end; gap: var(--pv-s2); }
.pivot-sim-container.pv .pv-counter { font-size: 15px; color: var(--pv-ink-2); display: flex; align-items: baseline; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
.pivot-sim-container.pv .pv-counter strong { font-size: 22px; color: var(--pv-ink); }
.pivot-sim-container.pv .pv-cal { margin-left: var(--pv-s2); background: var(--pv-accent-soft); color: var(--pv-accent-ink); font-weight: 650; font-size: 13px; padding: 2px 10px; border-radius: 999px; }
.pivot-sim-container.pv .pv-steps { list-style: none; display: flex; gap: 6px; padding: 0; margin: 0; }
.pivot-sim-container.pv .pv-steps li { width: 64px; text-align: center; font-size: 12px; color: var(--pv-ink-3); border-top: 4px solid var(--pv-line-2); padding-top: 3px; border-radius: 2px; }
.pivot-sim-container.pv .pv-steps li.is-done { border-top-color: var(--pv-navy); color: var(--pv-ink-2); }
.pivot-sim-container.pv .pv-steps li.is-now { border-top-color: var(--pv-accent); color: var(--pv-ink); font-weight: 700; }

/* layout */
.pivot-sim-container.pv .pv-grid { display: grid; grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr); gap: var(--pv-s4); align-items: start; }
.pivot-sim-container.pv .pv-col { display: flex; flex-direction: column; gap: var(--pv-s3); min-width: 0; }
.pivot-sim-container.pv .pv-card { background: var(--pv-card); border: 1px solid var(--pv-line); border-radius: var(--pv-r); padding: var(--pv-s4); box-shadow: 0 1px 2px rgba(11,31,58,.05); }
.pivot-sim-container.pv .pv-h2 { font-size: 18px; font-weight: 700; line-height: 1.3; color: var(--pv-ink); }
.pivot-sim-container.pv .pv-h3 { font-size: 15px; font-weight: 700; color: var(--pv-ink); margin-bottom: var(--pv-s2); display: block; }
.pivot-sim-container.pv .pv-muted { font-size: 13.5px; color: var(--pv-ink-3); }

/* briefing */
.pivot-sim-container.pv .pv-brief { border-left: 4px solid var(--pv-accent); }
.pivot-sim-container.pv .pv-tag { display: inline-block; font-size: 12px; font-weight: 700; color: var(--pv-accent-ink); background: var(--pv-accent-soft); padding: 2px 10px; border-radius: 999px; margin-bottom: var(--pv-s2); }
.pivot-sim-container.pv .pv-brief-text { margin-top: var(--pv-s2); color: var(--pv-ink-2); font-size: 14.5px; }
.pivot-sim-container.pv .pv-quote { margin-top: var(--pv-s3); padding: var(--pv-s3) var(--pv-s4); background: var(--pv-navy); color: #f4f7fb; border-radius: var(--pv-r-sm); font-size: 13.5px; line-height: 1.5; }
.pivot-sim-container.pv .pv-signal { margin-top: var(--pv-s3); padding: var(--pv-s2) var(--pv-s3); background: var(--pv-amber-soft); border-left: 3px solid var(--pv-amber); border-radius: var(--pv-r-sm); font-size: 13.5px; color: #5c2d05; }

/* KPIs */
.pivot-sim-container.pv .pv-kpis { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--pv-s3); }
.pivot-sim-container.pv .pv-kpi { background: var(--pv-card); border: 1px solid var(--pv-line); border-radius: var(--pv-r); padding: var(--pv-s3) var(--pv-s4); }
.pivot-sim-container.pv .pv-kpi-label { font-size: 13px; font-weight: 600; color: var(--pv-ink-3); }
.pivot-sim-container.pv .pv-kpi-value { font-size: 24px; font-weight: 750; color: var(--pv-ink); font-variant-numeric: tabular-nums; margin: 2px 0; }
.pivot-sim-container.pv .pv-kpi-value small { font-size: 14px; font-weight: 600; color: var(--pv-ink-3); margin-left: 2px; }
.pivot-sim-container.pv .pv-kpi-value.is-neg { color: var(--pv-bad); }
.pivot-sim-container.pv .pv-kpi-sub { font-size: 12.5px; color: var(--pv-ink-3); }
.pivot-sim-container.pv .pv-up { color: var(--pv-ok); font-weight: 650; }
.pivot-sim-container.pv .pv-down { color: var(--pv-bad); font-weight: 650; }
.pivot-sim-container.pv .pv-flat { color: var(--pv-ink-3); font-weight: 600; }

/* scorecard */
.pivot-sim-container.pv .pv-score-head { display: flex; align-items: center; gap: var(--pv-s3); flex-wrap: wrap; margin-bottom: var(--pv-s2); }
.pivot-sim-container.pv .pv-score-head .pv-h3 { margin: 0; flex: 1 1 auto; }
.pivot-sim-container.pv .pv-score-n strong { font-size: 24px; font-weight: 750; font-variant-numeric: tabular-nums; }
.pivot-sim-container.pv .pv-score-n small { color: var(--pv-ink-3); }
.pivot-sim-container.pv .pv-chip { display: inline-block; font-size: 12.5px; font-weight: 700; padding: 3px 10px; border-radius: 999px; border: 1px solid transparent; }
.pivot-sim-container.pv .pv-chip-seriesA { background: var(--pv-ok-soft); color: var(--pv-ok); border-color: #b7e0c4; }
.pivot-sim-container.pv .pv-chip-onTrack { background: var(--pv-accent-soft); color: var(--pv-accent-ink); border-color: #b6dfea; }
.pivot-sim-container.pv .pv-chip-mixed { background: var(--pv-warn-soft); color: #7a4a00; border-color: #f2d48f; }
.pivot-sim-container.pv .pv-chip-confused { background: var(--pv-amber-soft); color: #8a3c04; border-color: #f4c99a; }
.pivot-sim-container.pv .pv-chip-halted { background: var(--pv-bad-soft); color: var(--pv-bad); border-color: #f2b8b2; }
.pivot-sim-container.pv .pv-bar { display: grid; grid-template-columns: 11em 1fr 2.5em; gap: var(--pv-s2); align-items: center; font-size: 13.5px; margin: 6px 0; }
.pivot-sim-container.pv .pv-bar-l { color: var(--pv-ink-2); }
.pivot-sim-container.pv .pv-bar-t { height: 8px; background: #e7ecf3; border-radius: 999px; overflow: hidden; }
.pivot-sim-container.pv .pv-bar-f { display: block; height: 100%; border-radius: 999px; }
.pivot-sim-container.pv .pv-bar-f.f1 { background: var(--pv-accent); }
.pivot-sim-container.pv .pv-bar-f.f2 { background: #0f766e; }
.pivot-sim-container.pv .pv-bar-f.f3 { background: var(--pv-indigo); }
.pivot-sim-container.pv .pv-bar-f.f4 { background: var(--pv-navy); }
.pivot-sim-container.pv .pv-bar-v { text-align: right; font-variant-numeric: tabular-nums; font-weight: 650; color: var(--pv-ink-2); }
.pivot-sim-container.pv .pv-gates { display: flex; flex-wrap: wrap; gap: 6px; margin-top: var(--pv-s2); }
.pivot-sim-container.pv .pv-gchip { font-size: 12.5px; font-weight: 650; padding: 2px 9px; border-radius: 999px; border: 1px solid; }
.pivot-sim-container.pv .pv-gchip.is-ok { color: var(--pv-ok); background: var(--pv-ok-soft); border-color: #b7e0c4; }
.pivot-sim-container.pv .pv-gchip.is-no { color: var(--pv-bad); background: var(--pv-bad-soft); border-color: #f2b8b2; }
.pivot-sim-container.pv .pv-note { font-size: 12.5px; color: var(--pv-ink-3); margin-top: var(--pv-s2); }

/* result */
.pivot-sim-container.pv .pv-res { margin: 0; padding-left: 1.1em; font-size: 14px; color: var(--pv-ink-2); }
.pivot-sim-container.pv .pv-res li { margin: 4px 0; }

/* decisions */
.pivot-sim-container.pv .pv-dec-head { display: flex; justify-content: space-between; align-items: baseline; gap: var(--pv-s3); flex-wrap: wrap; margin-bottom: var(--pv-s2); }
.pivot-sim-container.pv .pv-dec-note { font-size: 13px; color: var(--pv-ink-3); flex: 1 1 14em; text-align: right; }
.pivot-sim-container.pv .pv-group { border: 1px solid var(--pv-line); border-radius: var(--pv-r); padding: var(--pv-s1) var(--pv-s4) var(--pv-s2); margin: 0 0 var(--pv-s3); min-width: 0; }
.pivot-sim-container.pv .pv-group legend { font-size: 12.5px; font-weight: 750; letter-spacing: .06em; text-transform: uppercase; color: var(--pv-accent-ink); padding: 0 6px; width: auto; float: none; margin: 0; }
.pivot-sim-container.pv .pv-field { padding: 6px 0; }
.pivot-sim-container.pv .pv-field + .pv-field { border-top: 1px dashed var(--pv-line); }
.pivot-sim-container.pv .pv-field-head { display: flex; justify-content: space-between; align-items: center; gap: var(--pv-s2); }
.pivot-sim-container.pv .pv-field label { font-size: 14.5px; font-weight: 650; color: var(--pv-ink); margin: 0; }
.pivot-sim-container.pv .pv-out { font-variant-numeric: tabular-nums; font-weight: 750; font-size: 14px; color: var(--pv-accent-ink); background: var(--pv-accent-soft); padding: 2px 10px; border-radius: 999px; white-space: nowrap; }
.pivot-sim-container.pv input[type="range"] { width: 100%; margin: 4px 0 0; accent-color: var(--pv-accent); height: 24px; background: transparent; cursor: pointer; }
.pivot-sim-container.pv .pv-scale { display: flex; justify-content: space-between; font-size: 12.5px; color: var(--pv-ink-3); }
.pivot-sim-container.pv .pv-hint { font-size: 13px; color: var(--pv-ink-2); margin-top: 2px; }
.pivot-sim-container.pv .pv-preview { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 4px var(--pv-s2); background: #f5f8fb; border: 1px solid var(--pv-line); border-radius: var(--pv-r); padding: var(--pv-s2) var(--pv-s3); }
.pivot-sim-container.pv .pv-pv span { display: block; font-size: 12px; color: var(--pv-ink-3); }
.pivot-sim-container.pv .pv-pv strong { font-size: 15px; font-variant-numeric: tabular-nums; color: var(--pv-ink); }
.pivot-sim-container.pv .pv-pv.is-neg strong { color: var(--pv-bad); }
.pivot-sim-container.pv .pv-preview-note { grid-column: 1 / -1; font-size: 12px; color: var(--pv-ink-3); }
.pivot-sim-container.pv .pv-validation { color: var(--pv-bad); font-weight: 600; font-size: 13.5px; margin: 6px 0; }
.pivot-sim-container.pv .pv-validation:empty { margin: 4px 0; }
.pivot-sim-container.pv .pv-actions { display: flex; gap: var(--pv-s3); flex-wrap: wrap; align-items: center; }
.pivot-sim-container.pv .pv-btn { min-height: 44px; padding: 10px 22px; border-radius: 10px; font-weight: 700; font-size: 15px; border: 1px solid transparent; cursor: pointer; font-family: inherit; letter-spacing: 0; text-transform: none; }
.pivot-sim-container.pv .pv-btn-primary { background: var(--pv-navy); color: #ffffff; }
.pivot-sim-container.pv .pv-btn-primary:hover { background: #163563; }
.pivot-sim-container.pv .pv-btn-primary:disabled { background: #8b98ab; cursor: not-allowed; }
.pivot-sim-container.pv .pv-btn-ghost { background: transparent; color: var(--pv-ink-2); border-color: var(--pv-line-2); }
.pivot-sim-container.pv .pv-btn-ghost:hover { background: #eef2f7; }
.pivot-sim-container.pv :focus-visible { outline: 3px solid var(--pv-focus); outline-offset: 2px; border-radius: 6px; }

/* debrief */
.pivot-sim-container.pv .pv-debrief { border-top: 4px solid var(--pv-navy); }
.pivot-sim-container.pv .pv-debrief-score { display: flex; align-items: baseline; gap: var(--pv-s2); margin: var(--pv-s2) 0 2px; flex-wrap: wrap; }
.pivot-sim-container.pv .pv-debrief-score strong { font-size: 44px; line-height: 1; font-weight: 800; font-variant-numeric: tabular-nums; }
.pivot-sim-container.pv .pv-debrief-score small { font-size: 16px; color: var(--pv-ink-3); margin-right: var(--pv-s2); }
.pivot-sim-container.pv .pv-debrief-sub { font-size: 13.5px; color: var(--pv-ink-3); }
.pivot-sim-container.pv .pv-dkpis { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--pv-s2); margin: var(--pv-s3) 0; }
.pivot-sim-container.pv .pv-dkpi { border: 1px solid var(--pv-line); border-radius: var(--pv-r-sm); padding: var(--pv-s2) var(--pv-s3); background: #f8fafc; }
