.pivot-sim-container.pv .pv-rules li.is-ok { background: var(--pv-ok-soft); color: var(--pv-ok); }
.pivot-sim-container.pv .pv-rules li.is-no { background: var(--pv-bad-soft); color: var(--pv-bad); }
.pivot-sim-container.pv .pv-gate { font-size: 13.5px; color: #7a4a00; background: var(--pv-warn-soft); padding: 6px 10px; border-radius: var(--pv-r-sm); margin-bottom: var(--pv-s2); }
.pivot-sim-container.pv .pv-debrief h3 { font-size: 16px; font-weight: 700; margin: var(--pv-s4) 0 var(--pv-s2); }
.pivot-sim-container.pv .pv-turning { background: var(--pv-amber-soft); border-left: 3px solid var(--pv-amber); padding: var(--pv-s2) var(--pv-s3); border-radius: var(--pv-r-sm); font-size: 14.5px; }
