.pivot-sim-container.pv .pv-chart-box { position: relative; height: 260px; background: none; border: 0; padding: 0; }
.pivot-sim-container.pv .pv-chart-alt { font-size: 12.5px; color: var(--pv-ink-3); margin-top: var(--pv-s2); }
.pivot-sim-container.pv .pv-table-wrap { overflow-x: auto; border: 1px solid var(--pv-line); border-radius: var(--pv-r-sm); margin-bottom: var(--pv-s4); }
.pivot-sim-container.pv table.pv-table, .pivot-sim-container.pv .pv-table.table { width: 100%; border-collapse: collapse; font-size: 13.5px; color: var(--pv-ink); background: var(--pv-card); margin: 0; }
