    .pivot-sim-container.pv .pv-progress { align-items: flex-start; }
    .pivot-sim-container.pv .pv-counter { justify-content: flex-start; }
    .pivot-sim-container.pv .pv-steps li { width: auto; flex: 1 1 0; white-space: nowrap; font-size: 11.5px; }
    .pivot-sim-container.pv .pv-dec-note { text-align: left; }
    .pivot-sim-container.pv .pv-preview { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .pivot-sim-container.pv .pv-dkpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .pivot-sim-container.pv .pv-kpi { padding: var(--pv-s2) var(--pv-s3); }
