        /* ---------- reading a run ---------- */
        _flags(ds) {
            var h = ds.hist || [];
            var by = function (t) { for (var i = 0; i < h.length; i++) { if (h[i].t === t) { return h[i]; } } return null; };
            var r1 = by(1), r2 = by(2), r3 = by(3), r4 = by(4);
            var has = function (r, n) { return !!(r && r.notes.indexOf(n) >= 0); };
            var budgets = h.map(function (r) { return r.budget; });
            var avgB = budgets.length ? budgets.reduce(function (a, b) { return a + b; }, 0) / budgets.length : 0;
            return {
                r1: r1, r2: r2, r3: r3, r4: r4,
                hedge: (r1 && r1.w <= 0.55) || (r2 && r2.w < 0.6),
                hedgeR1: r1 && r1.w <= 0.55,
                totalNo: has(r1, 'diag_total'),
                poc: has(r2, 'poc'),
                burn: avgB >= 38 || (r4 && r4.budget >= 40),
                cutMkt: (r3 && r3.budget <= 8) || (r4 && r4.budget <= 8),
                deepCut: has(r2, 'deepcut'),
                oversimp: has(r2, 'oversimp'),
                underfunded: r2 && r2.budget <= 8,
                noConc: has(r3, 'no_concessions'),
                softCommit: r3 && r3.w < 0.75,
                preference: has(r3, 'preference'),
                bigConc: has(r3, 'big_concessions'),
                scary: has(r3, 'scary_burn'),
                neglect: has(r4, 'neglect'),
                rushed: has(r4, 'rushed'),
                slow: has(r4, 'slow_launch'),
                deal: h.some(function (r) { return r.notes.indexOf('ent_deal') >= 0; }),
                flips: ds.flips || 0,
                shortRw: (ds.runway || 0) < 6
            };
        }

        _analyse(ds) {
            var h = ds.hist || [];
            var ins = [], qs = [];
            if (!h.length) { return { insights: ins, turning: '', questions: qs }; }
            var f = this._flags(ds);
            var last = h[h.length - 1];
            var M = PVModel.M;
            var self = this;
            /* the turning point: the first real mistake, named by its cause; otherwise the hardest moment */
            var turning = '';
            if (f.hedgeR1) { turning = this._t('tp_hedge', { w: this._num(f.r1.sme, 0) }); }
            else if (f.deepCut || f.underfunded) { turning = this._t(f.deepCut ? 'tp_deepcut' : 'tp_underfunded', { r: f.r2.risk, b: this._k(f.r2.budget) }); }
            else if (f.hedge) { turning = this._t('tp_hedge2', { w: this._num(f.r2.sme, 0) }); }
            else if (f.noConc || f.softCommit) { turning = this._t(f.noConc ? 'tp_noconc' : 'tp_soft', { w: this._num(f.r3.sme, 0), d: this._sign(f.r3.dK, 0) }); }
            else if (f.burn) { turning = this._t('tp_burn', { rw: this._mo(last.runway) }); }
            else if (f.cutMkt) { turning = this._t('tp_cutmkt'); }
            else if (f.neglect) { turning = this._t('tp_neglect', { c: this._pct(last.churn) }); }
            else {
                var worst = null, prevS = null;
                for (var i = 0; i < h.length; i++) { var d = prevS == null ? 0 : h[i].score - prevS; if (worst == null || d < worst.d) { worst = { d: d, t: h[i].t }; } prevS = h[i].score; }
                turning = this._t('tp_none', { m: this._t('cal_' + (worst ? worst.t : 1)), s: last.score });
            }
            /* insights built from what this run did */
            if (f.hedge) { ins.push(this._t('ins_hedge', { p: f.poc ? this._t('ins_hedge_poc') : '', d: f.deal ? this._t('ins_hedge_deal') : this._t('ins_hedge_nodeal') })); }
            else if (f.totalNo) { ins.push(this._t('ins_total')); }
            else { ins.push(this._t('ins_diag', { w: this._num(f.r1 ? f.r1.sme : 0, 0) })); }
            if (f.deepCut) { ins.push(this._t('ins_deepcut', { n: ds.mediumLost || 0 })); }
            else if (f.oversimp) { ins.push(this._t('ins_oversimp', { n: ds.mediumLost || 0 })); }
            else if (f.underfunded) { ins.push(this._t('ins_underfunded', { s: this._num(f.r2 ? f.r2.simp : 0, 0) })); }
            ins.push(this._t('ins_churn', { a: this._pct(M.CH0), b: this._pct(last.churn), s: this._num(last.shipped, 0) }));
            if (f.burn) { ins.push(this._t('ins_burn', { rw: this._mo(last.runway), c: this._k(last.cash) })); }
            else if (f.cutMkt) { ins.push(this._t('ins_cutmkt', { n: this._num(f.r4 ? f.r4.newClients : 0, 1) })); }
            if (f.noConc) { ins.push(this._t('ins_noconc')); }
            else if (f.softCommit) { ins.push(this._t('ins_soft')); }
            else if (f.preference) { ins.push(this._t('ins_preference')); }
            else if (f.r3) { ins.push(this._t('ins_angels', { d: this._sign(f.r3.dK, 0), k: f.r3.K })); }
            if (f.neglect) { ins.push(this._t('ins_neglect')); }
            if (f.flips) { ins.push(this._t('ins_flips', { n: f.flips })); }
            ins.push(this._t('ins_numbers', { arr: this._k(last.arr), c: this._num(last.clients, 0), ch: this._pct(last.churn), k: last.K, rw: this._mo(last.runway) }));
            ins = ins.slice(0, 5);
            /* questions for class, from the concept's debrief sequence */
            qs.push(f.hedge ? this._t('q_pmf_hedge') : this._t('q_pmf'));
            qs.push(f.noConc || f.softCommit ? this._t('q_angels_rev') : this._t('q_angels'));
            qs.push(last.arr >= M.ARR_T ? this._t('q_18m', { arr: this._k(last.arr) }) : this._t('q_enterprise'));
            return { insights: ins, turning: turning, questions: qs };
        }

        _debriefHTML(ds, summary) {
            var h = ds.hist || [];
            if (!h.length) { return ''; }
            var last = h[h.length - 1], perf = ds.performance || {}, s = perf.overallScore || 0, tier = perf.tier || PVModel.tier(s);
            var a = this._analyse(ds);
            var M = PVModel.M;
            var k = function (label, val) { return '<div class="pv-dkpi"><span>' + label + '</span><strong>' + val + '</strong></div>'; };
            var rule = function (ok, txt) { return '<li class="' + (ok ? 'is-ok' : 'is-no') + '">' + (ok ? '✓ ' : '✗ ') + txt + '</li>'; };
            var cap = perf.cap ? '<p class="pv-gate">' + this._t('cap_' + perf.cap) + '</p>' : '';
            return '<div class="pv-debrief-head">'
                + '<p class="pv-kicker">' + this._t('d_kicker') + '</p>'
                + '<h2 class="pv-h2" id="pvDebriefTitle">' + this._t('d_title') + '</h2>'
                + '<p class="pv-debrief-score"><strong>' + s + '</strong><small>/100</small><span class="pv-chip pv-chip-' + tier + '">' + this._t('perf_' + tier) + '</span></p>'
                + '<p class="pv-debrief-sub">' + this._t('d_sub', { o: perf.outcome, p: perf.process }) + '</p></div>'
                + '<div class="pv-dkpis">'
                + k(this._t('kpi_arr_short'), this._k(last.arr)) + k(this._t('d_k_clients'), this._num(last.clients, 0)) + k(this._t('kpi_churn'), this._pct(last.churn))
                + k(this._t('kpi_conf_short'), this._num(last.K, 0)) + k(this._t('d_k_cash'), this._k(last.cash)) + k(this._t('d_k_runway'), this._mo(last.runway)) + '</div>'
                + '<ul class="pv-rules">'
                + rule(last.arr >= M.ARR_T, this._t('d_rule_arr', { v: this._k(last.arr) }))
                + rule(last.churn <= M.CHURN_T, this._t('d_rule_churn', { v: this._pct(last.churn) }))
                + rule(last.K >= M.CONF_T, this._t('d_rule_conf', { v: last.K })) + '</ul>'
                + cap
                + '<h3>' + this._t('d_turning') + '</h3><p class="pv-turning">' + a.turning + '</p>'
                + '<h3>' + this._t('d_insights') + '</h3><ul class="pv-insights">' + a.insights.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>'
                + '<h3>' + this._t('d_questions') + '</h3><ol class="pv-questions">' + a.questions.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ol>';
        }

        /* ---------- painting ---------- */
        _runOver(st) {
            try { if (window.mySimulation && typeof window.mySimulation.isRunComplete === 'function') { return !!window.mySimulation.isRunComplete(); } } catch (e) {}
            var maxP = (st && st.maxPeriods) || PV_R;
            if (st && st.currentPeriod > maxP) { return true; }
            var h = (st && st.history) || (window.mySimulation && window.mySimulation.history) || [];
            return h.length >= maxP;
        }

        _bind() {
            if (this._bound) { return; }
            this._bound = true;
            var self = this;
            PV_IDS.forEach(function (id) {
                var el = document.getElementById(id);
                if (!el) { return; }
                var hnd = function () { try { self._paintOutputs(); self._paintHints(); self._paintPreview(); var v = self._el('pvValidation'); if (v) { v.textContent = ''; } } catch (e) {} };
                el.addEventListener('input', hnd);
                el.addEventListener('change', hnd);
            });
            var relang = function () { try { self._render(); self._relabelCharts(); } catch (e) {} };
            document.addEventListener('express:langchanged', relang);
            var f = window.mySimulation;
            if (f && f.eventBus && typeof f.eventBus.on === 'function') {
                f.eventBus.on('language:changed', relang);
                f.eventBus.on('period:submitted', function () {
                    try { self._syncControls(); self._render(); } catch (e) {}
                    setTimeout(function () { try { self._paintOutputs(); self._paintHints(); self._paintPreview(); } catch (e) {} }, 60);
                });
                f.eventBus.on('period:undone', function () { try { self._syncControls(); self._render(); } catch (e) {} });
                f.eventBus.on('state:loaded', function () { try { self._syncControls(); self._render(); } catch (e) {} });
                f.eventBus.on('simulation:complete', function () { try { self._render(); } catch (e) {} });
            }
        }

        /* On resume, undo or a new round the sliders show the player's own last choices, not the authored defaults. */
        _syncControls() {
            var st = this._state();
            if (!st) { return; }
            var d = st.decisions || {};
            var put = function (id, v) { var el = document.getElementById(id); if (el && v !== undefined && v !== null && v !== '' && isFinite(Number(v))) { el.value = String(v); } };
            put('smeWeightInput', d.smeWeight); put('budgetInput', d.budget); put('riskInput', d.risk);
            this._paintOutputs();
        }

        _render() {
            var st = this._state();
            if (!st || !st.domainState) { return; }
            var ds = st.domainState;
            var over = this._runOver(st);
            var t = over ? PV_R : this._round();
            this._paintStatic(t, over);
            this._paintSteps(t, over);
            this._paintBriefing(t, over);
            this._paintKpis(ds);
            this._paintScore(ds);
            this._paintResult(ds);
            this._paintOutputs();
            this._paintHints();
            this._paintPreview();
            this._paintChartAlt(ds);
            var form = this._el('pvForm'), deb = this._el('debriefPanel');
            if (over) {
                if (form) { form.hidden = true; }
                if (deb) { deb.innerHTML = this._debriefHTML(ds, this.getPerformanceSummary(st.history)); deb.hidden = false; }
            } else {
                if (form) { form.hidden = false; }
                if (deb) { deb.hidden = true; deb.innerHTML = ''; }
            }
            try { document.documentElement.lang = this._lang(); } catch (e) {}
        }

        _paintStatic(t, over) {
            var terms = ['pmf', 'arr', 'churn', 'nrr', 'runway', 'cac', 'ltv', 'pivot', 'poc', 'seriesA'];
            var html = '';
            for (var i = 0; i < terms.length; i++) { html += '<dt>' + this._t('g_' + terms[i]) + '</dt><dd>' + this._t('g_' + terms[i] + '_d') + '</dd>'; }
            this._set('pvGlossary', html);
            var tt = Math.min(t, PV_R);
            this._set('pvLegend', this._t('legend_' + tt));
            this._set('pvDecNote', this._t('dec_note_' + tt));
            var lab = function (id, k) { var e = document.getElementById(id); if (e) { var l = k; if (e.textContent !== l) { e.textContent = l; } } };
            lab('smeLabel', this._t('sme_label_' + tt));
            lab('budgetLabel', this._t('budget_label_' + tt));
            lab('riskLabel', this._t('risk_label_' + tt));
            var sc = function (a, b) { return '<span>' + a + '</span><span>' + b + '</span>'; };
            this._set('smeScale', sc(this._t('sme_lo_' + tt), this._t('sme_hi_' + tt)));
            this._set('budgetScale', sc(this._k(PVModel.M.B_MIN), this._k(PVModel.M.B_MAX)));
            this._set('riskScale', sc(this._t('risk_lo_' + tt), this._t('risk_hi_' + tt)));
        }

        _paintSteps(t, over) {
            var html = '';
            var st = this._state(), done = (st && st.history) ? st.history.length : 0;
            for (var i = 1; i <= PV_R; i++) {
                var cls = (i <= done) ? 'is-done' : (i === t && !over ? 'is-now' : '');
                html += '<li class="' + cls + '"><span>' + this._t('cal_short_' + i) + '</span></li>';
            }
            this._set('pvSteps', html);
            var c = this._el('pvCal');
            if (c) { var txt = over ? this._t('run_complete') : this._t('cal_' + t); if (c.textContent !== txt) { c.textContent = txt; } }
        }

        _paintBriefing(t, over) {
            var ds = (this._state() || {}).domainState || {};
            var h = ds.hist || [];
            this._set('pvTag', over ? this._t('tag_done') : this._t('tag_' + t));
            this._set('pvBriefTitle', over ? this._t('brief_done_title') : this._t('brief_title_' + t));
            this._set('briefingText', over ? '<p>' + this._t('brief_done') + '</p>' : '<p>' + this._t('brief_' + t) + '</p>');
            var q = this._el('pvQuote');
            if (q) {
                var qt = over ? '' : this._t('quote_' + t);
                if (qt && qt !== 'quote_' + t) { this._set('pvQuote', qt); q.hidden = false; } else { q.hidden = true; }
            }
            var sig = [];
            if (!over) {
                var prev = h[h.length - 1];
                if (t === 2 && prev && prev.w <= 0.55) { sig.push(this._t('sig_poc')); }
                if (t === 3 && ds.shipped >= 0.5) { sig.push(this._t('sig_shipped', { s: this._num(ds.shipped * 100, 0) })); }
                if (t === 3 && ds.bumpMonths > 0) { sig.push(this._t('sig_bump')); }
                if (t === 4 && ds.shipped < 0.5) { sig.push(this._t('sig_noship')); }
                if (t === 4 && ds.K < 45) { sig.push(this._t('sig_angels_low', { k: ds.K })); }
            }
            var sg = this._el('pvSignal');
            if (sg) { if (sig.length) { this._set('pvSignal', sig.join('<br>')); sg.hidden = false; } else { sg.hidden = true; } }
        }

        _delta(cur, prev, dec, good, unit) {
            if (prev == null) { return ''; }
            var d = cur - prev;
            if (Math.abs(d) < Math.pow(10, -(dec || 0)) / 2) { return '<span class="pv-flat">± 0</span> '; }
            var ok = good === 'down' ? d < 0 : d > 0;
            return '<span class="' + (ok ? 'pv-up' : 'pv-down') + '">' + (d > 0 ? '▲ ' : '▼ ') + this._num(Math.abs(d), dec) + (unit || '') + '</span> ';
        }

        _paintKpis(ds) {
            var h = ds.hist || [], last = h[h.length - 1];
            var M = PVModel.M;
            var s0 = last ? last.start : null;
            this._set('arrDisplay', this._k(ds.arr));
            this._set('arrSub', last ? this._delta(last.arr, s0.arr, 0, 'up', this._lang() === 'es' ? ' mil' : 'K') + this._t('arr_sub', { c: this._num(ds.clients, 0), p: this._k(PVModel.pathArr(ds.month)), t: this._k(M.ARR_T) })
                : this._t('arr_sub0', { c: M.C0, t: this._k(M.ARR_T) }));
            this._set('churnDisplay', this._pct(ds.churn));
            this._set('churnSub', last ? this._delta(last.churn, s0.churn, 1, 'down', this._lang() === 'es' ? ' pp' : ' pp') + this._t('churn_sub', { t: this._pct(M.CHURN_T, 0) }) : this._t('churn_sub0', { t: this._pct(M.CHURN_T, 0) }));
            this._set('confidenceDisplay', this._num(ds.K, 0) + '<small>/100</small>');
            this._set('confSub', last ? this._delta(last.K, s0.K, 0, 'up') + this._t('conf_sub', { t: M.CONF_T }) : this._t('conf_sub0', { t: M.CONF_T }));
            this._set('cashDisplay', this._k(ds.cash));
            this._set('cashSub', this._t('cash_sub', { rw: this._mo(ds.runway) }));
            var cv = this._el('cashDisplay'); if (cv) { cv.classList.toggle('is-neg', ds.cash < 0 || ds.runway < 6); }
            var kv = this._el('confidenceDisplay'); if (kv) { kv.classList.toggle('is-neg', ds.K < 40); }
        }

        _paintScore(ds) {
            var h = ds.hist || [];
            var M = PVModel.M;
            if (!this._el('pvScoreCard')) { return; }
            var chip = function (ok, txt) { return '<span class="pv-gchip ' + (ok ? 'is-ok' : 'is-no') + '">' + (ok ? '✓ ' : '× ') + txt + '</span>'; };
            var gates = '<div class="pv-gates">' + chip(ds.arr >= M.ARR_T, this._t('gate_arr', { v: this._k(M.ARR_T) })) + chip(ds.churn <= M.CHURN_T, this._t('gate_churn', { v: this._pct(M.CHURN_T, 0) }))
                + chip(ds.K >= M.CONF_T, this._t('gate_conf', { v: M.CONF_T })) + '</div>';
            if (!h.length) { this._set('pvScoreCard', '<p class="pv-h3">' + this._t('score_title') + '</p><p class="pv-muted">' + this._t('score_empty') + '</p>' + gates); return; }
            var p = ds.performance || {};
            var bar = function (label, v, cls) { var w = Math.round(100 * Math.max(0, Math.min(1, v))); return '<div class="pv-bar"><span class="pv-bar-l">' + label + '</span><span class="pv-bar-t"><span class="pv-bar-f ' + cls + '" style="width:' + w + '%"></span></span><span class="pv-bar-v">' + w + '</span></div>'; };
            var html = '<div class="pv-score-head"><span class="pv-h3">' + this._t('score_title') + '</span><span class="pv-score-n"><strong>' + p.overallScore + '</strong><small>/100</small></span>'
                + '<span class="pv-chip pv-chip-' + p.tier + '">' + this._t('perf_' + p.tier) + '</span></div>'
                + bar(this._t('sb_arr'), p.arr, 'f1') + bar(this._t('sb_churn'), p.churn, 'f2') + bar(this._t('sb_conf'), p.confidence, 'f3')
                + bar(this._t('sb_disc'), (p.process || 0) / 100, 'f4') + gates
                + '<p class="pv-note">' + this._t('score_note') + '</p>';
            this._set('pvScoreCard', html);
        }

        _paintResult(ds) {
            var h = ds.hist || [];
            if (!h.length) { this._set('pvResultPanel', '<p class="pv-h3">' + this._t('res_title0') + '</p><p class="pv-muted">' + this._t('res_empty') + '</p>'); return; }
            var r = h[h.length - 1];
            var li = [];
            li.push(this._t('res_clients', { a: this._num(r.start.clients, 0), n: this._num(r.newClients, 1), l: this._num(r.lost, 1), b: this._num(r.clients, 0) }));
            li.push(this._t('res_arr', { a: this._k(r.start.arr), b: this._k(r.arr) }));
            var why = [];
            if (r.notes.indexOf('deepcut') >= 0) { why.push(this._t('why_deepcut')); }
            if (r.notes.indexOf('oversimp') >= 0) { why.push(this._t('why_oversimp')); }
            if (r.shipped >= 50 && r.month >= 3 && (h.length < 2 || h[h.length - 2].shipped < 50)) { why.push(this._t('why_shipped')); }
            if (r.notes.indexOf('neglect') >= 0) { why.push(this._t('why_neglect')); }
            if (r.notes.indexOf('rushed') >= 0) { why.push(this._t('why_rushed')); }
            li.push(this._t('res_churn', { a: this._pct(r.start.churn), b: this._pct(r.churn) }) + (why.length ? ' ' + why.join(' ') : ''));
            var names = { pitch: 'pp_pitch', door: 'pp_door', timid: 'pp_timid', flip: 'pp_flip', commit: 'pp_commit', spend: 'pp_spend', concede: 'pp_concede', evidence: 'pp_evidence', metrics: 'pp_metrics', runway: 'pp_runway', deal: 'pp_deal' };
            var arr = [];
            for (var key in r.parts) { if (r.parts.hasOwnProperty(key) && Math.abs(r.parts[key]) >= 0.5) { arr.push([key, r.parts[key]]); } }
            arr.sort(function (a, b) { return Math.abs(b[1]) - Math.abs(a[1]); });
            var self = this;
            var pp = arr.slice(0, 4).map(function (x) { return self._t(names[x[0]] || x[0]) + ' ' + self._sign(x[1], 0); }).join(' · ');
            li.push(this._t('res_conf', { a: r.start.K, b: r.K, parts: pp || '—' }));
            if (r.notes.indexOf('poc') >= 0) { li.push(this._t('res_poc', { c: this._k(PVModel.M.ENT_POC) })); }
            if (r.notes.indexOf('ent_deal') >= 0) { li.push('<strong>' + this._t('res_deal', { v: this._k(PVModel.M.ENT_DEAL) }) + '</strong>'); }
            li.push(this._t('res_cash', { a: this._k(r.start.cash), b: this._k(r.cash), rw: this._mo(r.runway) }));
            this._set('pvResultPanel', '<p class="pv-h3">' + this._t('res_title', { m: this._t('cal_' + r.t) }) + '</p><ul class="pv-res">' + li.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>');
        }

        _paintOutputs() {
            var r = this._read();
            if (isFinite(r.smeWeight)) { this._set('smeOut', this._num(r.smeWeight, 0) + (this._lang() === 'es' ? ' %' : '%')); }
            if (isFinite(r.budget)) { this._set('budgetOut', this._k(r.budget) + this._t('per_month')); }
            if (isFinite(r.risk)) { this._set('riskOut', this._num(r.risk, 0) + ' / 10'); }
        }

        _band(v, cuts) { for (var i = 0; i < cuts.length; i++) { if (v <= cuts[i]) { return i; } } return cuts.length; }

        _paintHints() {
            var r = this._read(), t = this._round();
            if (!isFinite(r.smeWeight)) { return; }
            var sb = this._band(r.smeWeight, [30, 60, 90]);
            this._set('smeHint', this._t('sme_h' + t + '_' + sb, { w: this._num(r.smeWeight, 0), e: this._num(100 - r.smeWeight, 0) }));
            var st = this._state(), ds = (st && st.domainState) || {};
